import { $gl } from "../../WebGLUtil";
/**
 * @description 新規のColorBufferObjectを生成する
 *              Create a new ColorBufferObject
 *
 * @return {object}
 * @method
 * @protected
 */
export const execute = () => {
    const stencilBufferObject = {
        "id": 0,
        "resource": $gl.createRenderbuffer(),
        "width": 0,
        "height": 0,
        "area": 0,
        "dirty": false
    };
    return {
        "resource": $gl.createRenderbuffer(),
        "stencil": stencilBufferObject,
        "width": 0,
        "height": 0,
        "area": 0,
        "dirty": false
    };
};
